<?php session_start();require 'page-guard.php';require '../config/db_conn.php';require '../includes/csrf-token.php';require 'components.php';$conn->query("CREATE TABLE IF NOT EXISTS sections (SECTION_ID INT AUTO_INCREMENT PRIMARY KEY, SECTION VARCHAR(80) NOT NULL UNIQUE)");$sections=$conn->query("SELECT x.SECTION,COUNT(s.ID) total FROM (SELECT SECTION FROM sections UNION SELECT DISTINCT SECTION FROM students WHERE SECTION IS NOT NULL AND SECTION<>'') x LEFT JOIN students s ON s.SECTION=x.SECTION GROUP BY x.SECTION ORDER BY x.SECTION");adminHead('Settings');adminSidebar('settings','Settings','Manage administrator security and teacher sections'); ?>
